		&XMLWhenTaxLoading;
		&XMLWhenTaxClosing;





function onChange$GridVoucherTax$TaxCode(o) {o.grid.request(o, 'GetTaxRate', 'TaxCode', ['ma_thue'], o);}
function onChange$GridVoucherTax$TaxAccount(o) {o.grid.request(o, 'GetAccountType', 'AccountType', ['tk_thue_no'], o);}
function onChange$GridVoucherTax$Supplier(o) {o.grid.request(o, 'Supplier', 'Supplier', ['ma_kh'], o);}
function on$GridVoucherTax$ExecuteCommand(sender, e) {
	var action = e.type.Action, z = sender, o = e.type.Object, f = z.get_element().parentForm, g = z;
	switch (action) {
		case 'AfterRemoveRow':
			on$GridVoucherTax$RowChange(z, f);
			break;
		case 'AfterCloneRow':
			z.setItemFieldValue('stt_rec0', e.type.Value, '');
			on$GridVoucherTax$RowChange(z, f);
			break;
		case 'AfterInsertRow':
			var z = f.getItem("r30")._controlBehavior;
			setDefault$Voucher$Tax(f);
			break;
		case 'Check':
			if !(z.validRowExpression('ten_vt', '([ten_vt] != "")')) break;
			z.validRowExpression('ma_kh2', '([ma_thue] == "") || (![tk_cn]) || ([ma_kh2] != "")');
			break;
		&Clipboard.Event.Before;
		&Clipboard.Event.Before.Request;
		&Clipboard.Event.Before.Process;
		&Clipboard.Event.After;
		&Clipboard.Event.After.Process;
		case 'Retrieve':
			var z = f.getItem("r30")._controlBehavior;
			var d31 = f.getItem('d31')._controlBehavior;

			genTaxGrid(f, d31, z);
			break;
&GridExtraToolbarExecuteCommandScript;;
		default:
			break;
	}
}

function genTaxGrid(f, g, z){
	if (!f._inputInvoice){
		for(var i = z._rowCount; i > g._rowCount; i--){ 
			z._setActiveCell(z._getItem(i, 1));
			z._deleteRow();
			if (i > 1) {z._setActiveCell(z._getItem(i - 1, 1));}
		}

		if (g._rowCount > 0){
			for(var i = 1; i <= g._rowCount; i++){
				if (i > z._rowCount){
					z._appendRow(null,true);
					z._setActiveCell(z._getItem(i, 1));
					setDefault$Voucher$TaxAll(f);
				} else {
					setTaxAmount(i, g, z);
				}
			}
		}
	}
}

function setTaxAmount(row, g, z){
	var cTien = g._getColumnOrder('tien'), cTien_nt = g._getColumnOrder('tien_nt');
	var cTien_thue = z._getColumnOrder('t_tien'), cTien_thue_nt = z._getColumnOrder('t_tien_nt');

	z._setItemValue(row, cTien_thue, g._getItemValue(row, cTien));
	z._setItemValue(row, cTien_thue_nt, g._getItemValue(row, cTien_nt));

	z.assignExpression(row - 1, z.$a.z_t_thue);
	z.assignExpression(row - 1, z.$a.z_t_thue_nt);
	z.validExpression(null, null, [z.$a.t_thue_nt, z.$a.t_thue], [z.$a.t_tt_nt, z.$a.t_tt]);
}

function onChange$GridVoucherTax$(sender, eventArgs) {
	var o = eventArgs.get_object(), z = o.grid, f = z.get_element().parentForm, name = o.field.Name;
	switch (name) {
		case 't_tien_nt':
			z.validExpression(o, [z.$a.z_t_tien, z.$a.z_t_thue_nt, z.$a.z_t_thue], [z.$a.t_thue_nt, z.$a.t_thue], [z.$a.t_tt_nt, z.$a.t_tt]);
			break;
		case 't_thue_nt':
			z.validExpression(o, [z.$a.z_t_thue, z.$a.z_t_thue_tg], [z.$a.t_thue_nt, z.$a.t_thue], [z.$a.t_tt_nt, z.$a.t_tt]);
			break;
		case 't_tien':
			z.validExpression(o, [z.$a.z_t_thue], [z.$a.t_thue], [z.$a.t_tt], 't_thue');
			break;
		case 't_thue':
			z.validExpression(o, null, [z.$a.t_thue], [z.$a.t_tt]);
			break;
		default:
			break;
	}
}
function on$GridVoucherTax$RowChange(z, f) {
	z.executeAggregate([z.$a.t_thue_nt, z.$a.t_thue]);
	f.executeExpression([z.$a.t_tt_nt, z.$a.t_tt]);
}
function on$GridVoucherTax$ResponseComplete(sender, e) {
	var z = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = z.get_element().parentForm;
	switch (context) {
		case 'TaxCode':
			var r = result[0].Value;
			if (z._getItemValue(o.row, z._getColumnOrder('thue_suat')) != r) {
				z.setItemGridBehavior(o, [['thue_suat', result[0].Value, '', false]]);
				z.validExpression(o, [z.$a.z_t_thue_nt, z.$a.z_t_thue], [z.$a.t_thue_nt, z.$a.t_thue], [z.$a.t_tt_nt, z.$a.t_tt]);
			}
			z.setItemGridBehavior(o, [['tk_thue_no', result[1].Value, '', true], ['tk_cn', result[2].Value, '', false]]);
			break;
		case 'AccountType':
			z.setItemGridBehavior(o, [['tk_cn', result[0].Value, '', false]]);
			break;
		case 'Supplier':
			z.setItemGridBehavior(o, [['dia_chi', result[0].Value, '', true], ['ma_so_thue', result[1].Value, '', true]]);
			z.live(o, 'dia_chi');
			break;
		default:
			break;
	}
}
function dispose$GridVoucherTax$(z) {
	z.$a = null;
	try {z.remove_commandEvent(on$GridVoucherTax$ExecuteCommand);} catch (ex) {}
	try {z.remove_itemValueChanged(onChange$GridVoucherTax$);} catch (ex) {}
	try {z.remove_onResponseComplete(on$GridVoucherTax$ResponseComplete);} catch (ex) {}
}
function setDefaultTaxItems(z, row, columns, f, fields) {
	for (var i = 0; i < columns.length; i++) {
		if (fields) setDefaultTaxItem(z, row, columns[i], f, fields[i]);
			else setDefaultTaxItem(z, row, columns[i], f[i]);
	}
}
function setDefaultTaxItem(z, row, columnName, f, fieldName) {
	if (fieldName != null) z._setItemValue(row, z._getColumnOrder(columnName), f.getItemValue(fieldName));
		else z._setItemValue(row, z._getColumnOrder(columnName), f);
}
function load$GridVoucherTax$(z) {
	z.add_itemValueChanged(onChange$GridVoucherTax$);
	z.add_onResponseComplete(on$GridVoucherTax$ResponseComplete);
	z.add_commandEvent(on$GridVoucherTax$ExecuteCommand);
	&FormulaExpression;
	udf$Detail$(z);
}    


			/* <flatten type="Javascript"> */
function setDefault$Voucher$Tax(f) {
	var g = f.getItem("d31")._controlBehavior, z = f.getItem("r30")._controlBehavior, row = 1;
	if (z._rowCount > 1) {
		setDefaultTaxItems(z, z._activeRow > 0 ? z._activeRow : z._rowCount, ['ma_tc', 'ma_thue', 'thue_suat', 'tk_thue_no', 'tk_cn', 'ma_mau_ct'], [z._taxProperty, z._taxCode, z._taxRate, z._taxAccount, z._taxType, z._voucherTemplate]);
		return;
	}
	if ((z._rowCount > 0) && (z._getItemValue(row, z._getColumnOrder('so_ct0')) == '')) {
		setDefaultTaxItems(z, row, ['mau_bc', 'ma_tc', 'ma_thue', 'thue_suat', 'tk_thue_no', 'tk_cn', 'ma_mau_ct'],
			['3', z._taxProperty, z._taxCode, z._taxRate, z._taxAccount, z._taxType, z._voucherTemplate]);
		setDefaultTaxItems(z, row, ['so_ct0', 'so_seri0', 'ngay_ct0', 't_tien_nt', 't_tien', 'ma_kh', 'ten_kh', 'dia_chi', 'ma_so_thue'], f,
			['so_ct0', 'so_seri0', 'ngay_ct0', 't_tien_nt', 't_tien', 'ma_kh', 'ten_ncc', 'dia_chi', 'ma_so_thue']);
		z.assignExpression(row - 1, z.$a.z_t_thue);
		z.assignExpression(row - 1, z.$a.z_t_thue_nt);
		z.validExpression(null, null, [z.$a.t_thue_nt, z.$a.t_thue], [z.$a.t_tt_nt, z.$a.t_tt]);
		var max = g.max('tien') + 1;
		if (max > 0) z._getItem(1, z._getColumnOrder('ten_vt')).value = g._getItem(max, g._getColumnOrder('dien_giai')).value;
	}
}

function setDefault$Voucher$TaxAll(f) {
	var g = f.getItem("d31")._controlBehavior, z = f.getItem("r30")._controlBehavior;
	var row = z._rowCount;
	var tien = g._getItemValue(row, g._getColumnOrder('tien')), tien_nt = g._getItemValue(row, g._getColumnOrder('tien_nt'));
	if (z._rowCount > 0) {
		setDefaultTaxItems(z, z._rowCount, ['mau_bc', 'ma_tc', 'ma_thue', 'thue_suat', 'tk_thue_no', 'tk_cn', 'ma_mau_ct', 't_tien_nt', 't_tien'],
			['3', z._taxProperty, z._taxCode, z._taxRate, z._taxAccount, z._taxType, z._voucherTemplate, tien_nt, tien]);
		setDefaultTaxItems(z, z._rowCount, ['so_ct0', 'so_seri0', 'ngay_ct0', 'ma_kh', 'ten_kh', 'dia_chi', 'ma_so_thue'], f,
			['so_ct0', 'so_seri0', 'ngay_ct0', 'ma_kh', 'ten_ncc', 'dia_chi', 'ma_so_thue']);

		z.assignExpression(row - 1, z.$a.z_t_thue);
		z.assignExpression(row - 1, z.$a.z_t_thue_nt);
		z.validExpression(null, null, [z.$a.t_thue_nt, z.$a.t_thue], [z.$a.t_tt_nt, z.$a.t_tt]);
//		var max = g.max('tien') + 1;
//		if (max > 0) z._getItem(1, z._getColumnOrder('ten_vt')).value = g._getItem(max, g._getColumnOrder('dien_giai')).value;

		z._setItemValue(row, z._getColumnOrder('ten_vt'), g._getItemValue(row, g._getColumnOrder('dien_giai')));
	}
}
